using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions
{
    // DefaultJsonTypeInfoResolver knows how to produce metadata for any type
    // via reflection, so GetTypeInfo<T> will succeed for anything.
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// ──────────────────────────────────────────────────────────────────
// 1. Strongly-typed metadata — returns JsonTypeInfo<T> directly
// ──────────────────────────────────────────────────────────────────
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Typed metadata  : {personInfo.Type.Name}, kind = {personInfo.Kind}");

string json = JsonSerializer.Serialize(new Person("Ada", 36), personInfo);
Console.WriteLine($"Serialized      : {json}");

Person? roundTripped = JsonSerializer.Deserialize(json, personInfo);
Console.WriteLine($"Deserialized    : {roundTripped}");

// ──────────────────────────────────────────────────────────────────
// 2. Probe without throwing — TryGetTypeInfo
//    We swap in a resolver that only knows about Person,
//    so probing for int will return false instead of throwing.
// ──────────────────────────────────────────────────────────────────
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new PersonOnlyResolver()
};

if (limited.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? found))
    Console.WriteLine($"\nProbe Person    : found — {found!.Type.Name}");
else
    Console.WriteLine("\nProbe Person    : not found");

if (limited.TryGetTypeInfo(typeof(int), out _))
    Console.WriteLine("Probe int       : found");
else
    Console.WriteLine("Probe int       : not found (no exception thrown)");

// ── types ────────────────────────────────────────────────────────
record Person(string Name, int Age);

/// <summary>
/// A resolver that only produces metadata for <see cref="Person"/>.
/// </summary>
sealed class PersonOnlyResolver : IJsonTypeInfoResolver
{
    private readonly DefaultJsonTypeInfoResolver _inner = new();

    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options) =>
        type == typeof(Person) ? _inner.GetTypeInfo(type, options) : null;
}

